def priority(item: float, bins: np.ndarray) -> np.ndarray:
    diff = bins - item
    return np.where(diff >= 0, -diff, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    diff = bins - item
    target = 0.3 * item
    return np.where(diff >= 0, -np.abs(diff - target), -np.inf)
